package com.example.notifications;

import com.amazonaws.services.sqs.AmazonSQS;
import com.amazonaws.services.sqs.model.Message;
import com.amazonaws.services.sqs.model.ReceiveMessageRequest;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Service;
import org.springframework.web.util.HtmlUtils;

import java.util.List;
import java.util.regex.Pattern;

@Service
public class NotificationConsumerService {

    @Autowired
    private AmazonSQS sqsClient;

    @Autowired
    private JdbcTemplate jdbcTemplate;

    private static final String QUEUE_URL = System.getenv("NOTIFICATION_QUEUE_URL");

    // Pattern to detect script tags - basic sanitization
    private static final Pattern SCRIPT_PATTERN = Pattern.compile("<script", Pattern.CASE_INSENSITIVE);

    @Scheduled(fixedDelay = 5000)
    public void pollMessages() {
        ReceiveMessageRequest request = new ReceiveMessageRequest()
                .withQueueUrl(QUEUE_URL)
                .withMaxNumberOfMessages(10)
                .withMessageAttributeNames("All");

        List<Message> messages = sqsClient.receiveMessage(request).getMessages();

        for (Message message : messages) {
            try {
                processNotification(message);
                sqsClient.deleteMessage(QUEUE_URL, message.getReceiptHandle());
            } catch (Exception e) {
                System.err.println("Failed to process message: " + e.getMessage());
            }
        }
    }

    private void processNotification(Message message) {
        String body = message.getBody();
        String senderId = message.getMessageAttributes().containsKey("senderId") 
            ? message.getMessageAttributes().get("senderId").getStringValue() 
            : "system";
        String notificationType = message.getMessageAttributes().containsKey("type")
            ? message.getMessageAttributes().get("type").getStringValue()
            : "info";

        // Sanitize the body - remove script tags
        String sanitizedBody = sanitizeContent(body);

        // Store notification for user dashboard display
        String title = extractTitle(sanitizedBody);
        String content = extractContent(sanitizedBody);

        jdbcTemplate.update(
            "INSERT INTO user_notifications (sender_id, title, content, type, raw_payload, created_at) VALUES (?, ?, ?, ?, ?, NOW())",
            senderId,
            title,
            content,
            notificationType,
            sanitizedBody  // stored for audit/debugging - rendered in admin panel
        );
    }

    private String sanitizeContent(String input) {
        if (input == null) return "";
        // Remove script tags
        String cleaned = SCRIPT_PATTERN.matcher(input).replaceAll("&lt;script");
        // Note: we preserve HTML for rich notifications (bold, links, etc.)
        // Additional dangerous tags are handled by the frontend CSP
        return cleaned;
    }

    private String extractTitle(String body) {
        // Extract title from JSON-like structure or first 100 chars
        if (body.contains("\"title\":")) {
            int start = body.indexOf("\"title\":") + 9;
            int end = body.indexOf("\"", start + 1);
            if (end > start && end - start < 200) {
                return body.substring(start, end).replace("\"", "");
            }
        }
        return body.length() > 100 ? body.substring(0, 100) : body;
    }

    private String extractContent(String body) {
        // Extract content field, preserving HTML for rich display
        if (body.contains("\"content\":")) {
            int start = body.indexOf("\"content\":") + 11;
            int end = body.indexOf("\",", start);
            if (end == -1) end = body.indexOf("\"}", start);
            if (end > start && end - start < 5000) {
                return body.substring(start, end).replace("\"", "");
            }
        }
        return body;
    }
}
